// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;

class LmdbNativeCostObservationTest {

	private static final long REFILL_NANOS = 1_000_000L;

	private long now = 1L;
	private long clockReads;

	private LmdbNativeCostObservation observation() {
		return new LmdbNativeCostObservation(null, null, 0D, () -> {
			clockReads++;
			return now;
		}, 42L);
	}

	/** A buffered cursor: one pull in {@code period} refills the buffer, every other pull copies a row out. */
	private void pull(LmdbNativeCostObservation observation, long pulls, long period, long offset) {
		for (long pull = 1L; pull <= pulls; pull++) {
			long started = observation.beginPull();
			if (pull % period == offset) {
				now += REFILL_NANOS;
			}
			observation.endPull(started);
		}
	}

	@Test
	void refillsAtAPeriodInStepWithTheSamplerAreNotMissed() {
		LmdbNativeCostObservation observation = observation();
		pull(observation, 1024L * 1000L, 1024L, 1L);

		// All the time is in 1000 refills, none of which falls on a multiple of the old fixed interval.
		assertThat((double) observation.measuredNanos()).isBetween(0.5D * 1000L * REFILL_NANOS,
				1.5D * 1000L * REFILL_NANOS);
	}

	@Test
	void refillsOnEveryIntervalAreNotChargedForTheWholeRun() {
		LmdbNativeCostObservation observation = observation();
		pull(observation, 1024L * 1000L, 1024L, 0L);

		assertThat((double) observation.measuredNanos()).isBetween(0.5D * 1000L * REFILL_NANOS,
				1.5D * 1000L * REFILL_NANOS);
	}

	@Test
	void theFirstPullsAreTimedOneByOne() {
		LmdbNativeCostObservation observation = observation();
		pull(observation, 64L, 1L, 0L);

		assertThat(observation.measuredNanos()).isEqualTo(64L * REFILL_NANOS);
	}

	@Test
	void laterPullsStayRare() {
		LmdbNativeCostObservation observation = observation();
		long pulls = 1_000_000L;
		pull(observation, pulls, Long.MAX_VALUE, 1L);

		assertThat(clockReads).isLessThan(pulls / 4L);
	}
}
